import{_ as t,o as a,c as i,a0 as r}from"./chunks/framework.DYS8d9tm.js";const u=JSON.parse('{"title":"Unified Parsing Pipeline","description":"","frontmatter":{},"headers":[],"relativePath":"technical/data ingestion/unified_parsing_pipeline.md","filePath":"technical/data ingestion/unified_parsing_pipeline.md"}'),n={name:"technical/data ingestion/unified_parsing_pipeline.md"};function s(o,e,l,d,g,c){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="unified-parsing-pipeline" tabindex="-1">Unified Parsing Pipeline <a class="header-anchor" href="#unified-parsing-pipeline" aria-label="Permalink to &quot;Unified Parsing Pipeline&quot;">​</a></h1><p>This document details the multi-tiered parsing strategy used to process raw financial data (SMS, Email, and Statements).</p><h2 id="_1-parsing-hierarchy-priority-stack" tabindex="-1">1. Parsing Hierarchy (Priority Stack) <a class="header-anchor" href="#_1-parsing-hierarchy-priority-stack" aria-label="Permalink to &quot;1. Parsing Hierarchy (Priority Stack)&quot;">​</a></h2><p>To ensure high reliability and minimize reliance on expensive/unpredictable AI models, the system follows a strict execution order:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Priority</th><th style="text-align:left;">Layer</th><th style="text-align:left;">Description</th><th style="text-align:left;">Confidence</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>1</strong></td><td style="text-align:left;"><strong>Registered Parsers</strong></td><td style="text-align:left;">Hardcoded logic for specific banks (e.g., <code>HdfcEmailParser</code>).</td><td style="text-align:left;">95%+</td></tr><tr><td style="text-align:left;"><strong>2</strong></td><td style="text-align:left;"><strong>Pattern Parsers</strong></td><td style="text-align:left;">Regex-based rules defined by the user or learned from training.</td><td style="text-align:left;">90%</td></tr><tr><td style="text-align:left;"><strong>3</strong></td><td style="text-align:left;"><strong>AI Fallback</strong></td><td style="text-align:left;">Large Language Models (Gemini) used as a last resort for unknown formats.</td><td style="text-align:left;">85%</td></tr></tbody></table><h3 id="_1-1-goal-1-ai-usage" tabindex="-1">1.1 Goal: &lt; 1% AI Usage <a class="header-anchor" href="#_1-1-goal-1-ai-usage" aria-label="Permalink to &quot;1.1 Goal: &lt; 1% AI Usage&quot;">​</a></h3><p>The system is designed to &quot;learn&quot; from AI successes. When an email is successfully parsed by AI, it can be used to generate a <strong>Pattern Rule</strong>, moving that specific format into the Tier 2 (Regex) layer for all future occurrences.</p><hr><h2 id="_2-orchestration-logic" tabindex="-1">2. Orchestration Logic <a class="header-anchor" href="#_2-orchestration-logic" aria-label="Permalink to &quot;2. Orchestration Logic&quot;">​</a></h2><p>The <code>BatchIngestionPipeline</code> (in the Parser Microservice) orchestrates this flow:</p><ol><li><strong>Classification</strong>: Verify the content is financial.</li><li><strong>Static Sweep</strong>: Iterate through all <code>RegisteredParsers</code> in the <code>ParserRegistry</code>.</li><li><strong>Pattern Match</strong>: Run the <code>PatternParser</code> against the database of regex rules.</li><li><strong>AI Guardrail</strong>: Check if the content is &quot;AI-worthy&quot; (contains numbers, keywords).</li><li><strong>AI Batching</strong>: Group unknown items and send to Gemini.</li></ol><hr><h2 id="_3-observability-debugging" tabindex="-1">3. Observability &amp; Debugging <a class="header-anchor" href="#_3-observability-debugging" aria-label="Permalink to &quot;3. Observability &amp; Debugging&quot;">​</a></h2><h3 id="_3-1-itemized-logs" tabindex="-1">3.1 Itemized Logs <a class="header-anchor" href="#_3-1-itemized-logs" aria-label="Permalink to &quot;3.1 Itemized Logs&quot;">​</a></h3><p>Every ingestion session records individual <code>EmailSyncItemLog</code> entries. This allows developers and users to see:</p><ul><li><strong>Which parser was used</strong> (e.g., <code>HdfcSmsParser</code> vs <code>AI Batch</code>).</li><li><strong>Failure reasons</strong> (e.g., &quot;Non-financial content&quot;, &quot;No pattern matched&quot;).</li><li><strong>Direct links</strong> to the resulting transactions.</li></ul><h3 id="_3-2-parser-sandbox" tabindex="-1">3.2 Parser Sandbox <a class="header-anchor" href="#_3-2-parser-sandbox" aria-label="Permalink to &quot;3.2 Parser Sandbox&quot;">​</a></h3><p>The <strong>Parser Sandbox</strong> (Settings &gt; Parser) allows manual testing of raw text against the full pipeline. This is the primary tool for debugging new bank formats or verifying regex patterns before deployment.</p><hr><h2 id="_4-multi-tenancy-data-isolation" tabindex="-1">4. Multi-Tenancy &amp; Data Isolation <a class="header-anchor" href="#_4-multi-tenancy-data-isolation" aria-label="Permalink to &quot;4. Multi-Tenancy &amp; Data Isolation&quot;">​</a></h2><p>All parsing rules and logs are strictly partitioned by <code>tenant_id</code>.</p><ul><li><strong>Registered Parsers</strong>: Shared across all tenants (Global).</li><li><strong>Pattern Rules</strong>: Tenant-specific (unless marked as Global by Admin).</li><li><strong>Extraction Logs</strong>: Tenant-specific.</li></ul>',22)])])}const p=t(n,[["render",s]]);export{u as __pageData,p as default};
